def calculate_a(N):
    a = {1: 0}
    for n in range(2, N + 1):
        max_val = -1
        for i in range(1, n):
            val = a[i] + a[n - i] + min(i, n - i)
            if val > max_val:
                max_val = val
        a[n] = max_val
    return a

