def solve_sequence(N):
    # Initialize a list to store a_n, 1-indexed conceptually, 0-indexed implementation
    # a[i] will store a_{i+1}
    a = [0] * (N + 1)
    a[1] = 0

    # Known values from notes up to n=20, to ensure consistency
    initial_values = {
        1: 0, 2: 1, 3: 2, 4: 4, 5: 5, 6: 7, 7: 9, 8: 12, 9: 13, 10: 15,
        11: 17, 12: 20, 13: 22, 14: 25, 15: 28, 16: 32, 17: 33, 18: 35, 19: 37, 20: 40
    }
    for n, val in initial_values.items():
        if n <= N:
            a[n] = val

    for n in range(2, N + 1):
        if n <= 20:
            continue # Already set from initial values

        max_val = -1

        # Iterate over all possible partitions 1 <= i <= n - 1
        for i in range(1, n):
            # Note: a[i] is a_i, a[n-i] is a_{n-i}
            term = a[i] + a[n - i] + min(i, n - i)
            if term > max_val:
                max_val = term

        a[n] = max_val

    return a[N]

N_target = 2025
result = solve_sequence(N_target)
print(f"a_{N_target} = {result}")
